{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.5",
  "body": [
    {
      "type": "TextBlock",
      "text": "⚠️ Review Needs Your Approval",
      "weight": "Bolder",
      "size": "Large"
    },
    {
      "type": "FactSet",
      "facts": [
        { "title": "Review ID", "value": "@{agentParameters('ReviewID')}" },
        { "title": "Reviewer", "value": "@{agentParameters('ReviewName')}" },
        { "title": "Rating", "value": "⭐ @{agentParameters('ReviewRating')}" }
      ]
    },
    {
      "type": "TextBlock",
      "text": "Customer Review",
      "weight": "Bolder",
      "spacing": "Medium"
    },
    {
      "type": "TextBlock",
      "text": "@{agentParameters('CustomerReview')}",
      "wrap": true,
      "isSubtle": true
    },
    {
      "type": "TextBlock",
      "text": "Drafted Response",
      "weight": "Bolder",
      "spacing": "Medium"
    },
    {
      "type": "TextBlock",
      "text": "@{agentParameters('AgentResponse')}",
      "wrap": true
    },
    {
      "type": "Input.Text",
      "id": "analyst_notes",
      "placeholder": "Add notes or edits (optional)...",
      "isMultiline": true,
      "spacing": "Small"
    }
  ],
  "actions": [
    {
      "type": "Action.Submit",
      "title": "Approve & Send",
      "data": {
        "action": "approve"
      }
    },
    {
      "type": "Action.Submit",
      "title": "Edit & Resubmit",
      "data": {
        "action": "edit"
      }
    },
    {
      "type": "Action.Submit",
      "title": "Reject",
      "data": {
        "action": "reject"
      }
    }
  ]
}
